#
# check-actions-pinned.sh — шаг конвейера подключает чужой код ПО СОДЕРЖИМОМУ.
#
# ПРЕДМЕТ. Ссылка по тегу подвижна: содержимое шага меняется без единой правки
# в этом дереве, и такое изменение не видно ни в диффе, ни в обзоре, ни в
# истории — у нас не меняется ничего. Конвейер при этом привилегирован: он
# собирает и публикует образы.
#
# ЗАСТОЙ — РЕАЛЬНАЯ ЦЕНА, И ОНА НАЗВАНА ЗДЕСЬ, А НЕ ЗАКРЫТА. Закрепление заводилось
# вместе с механизмом, который его двигал сам; 2026-08-27 владелец снял автообновление
# зависимостей целиком, и теперь ОБЕ половины ссылки — хеш и комментарий с версией —
# двигает только человек. Закрепление без движения хуже подвижного тега: устаревший
# сканер безопасности не краснеет, он МОЛЧИТ.
#
# Кто об этом скажет: НИКТО АВТОМАТИЧЕСКИ. Недельный сторож pinned-tools-freshness
# сверяет с апстримом версии, запиненные ВНУТРИ шагов (`with:`, `go install`, curl),
# и `uses:` не читает вовсе. Значит отставание шагов конвейера от апстрима сегодня не
# отслеживает ни одна полоса — это ПРОБЕЛ, а не граница, и он назван, чтобы его не
# приняли за чьё-то решение.
#
# ГРАНИЦА. Проверяется ОБЪЯВЛЕНИЕ шага, а не всякая строка со словом `uses`:
# слово встречается в комментариях этого же дерева, и предикат по подстроке
# краснел бы на собственном объяснении.

set -euo pipefail

root="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$root"

declared=0
unpinned=0
findings=()

while IFS= read -r line; do
    file="${line%%:*}"
    rest="${line#*:}"
    lineno="${rest%%:*}"
    ref="$(printf '%s' "${rest#*:}" | sed -E 's/^[[:space:]]*(-[[:space:]]*)?uses:[[:space:]]*//; s/[[:space:]]*(#.*)?$//')"

    # Локальный составной шаг (`./…`) содержимого не тянет — он В ЭТОМ дереве.
    case "$ref" in ./*) continue ;; esac

    declared=$((declared + 1))
    # Сравнение БЕЗ трубы: `printf | grep -q` под `pipefail` даёт ложный отказ,
    # когда `grep` завершается рано и производитель получает SIGPIPE — тот самый
    # класс, который ловит гейт дерева (#658).
    if [[ ! "$ref" =~ @[0-9a-f]{40}$ ]]; then
        unpinned=$((unpinned + 1))
        findings+=("$file:$lineno: $ref — подключено по подвижной ссылке")
    fi
done < <(grep -rnE '^[[:space:]]*(-[[:space:]]*)?uses:[[:space:]]*[^[:space:]#]+' .github/workflows/ || true)

echo "осмотрено объявлений шага: $declared; из них не по содержимому: $unpinned"

if [[ "$declared" -eq 0 ]]; then
    echo "ОТКАЗ: ни одного объявления не прочитано — признак разошёлся с деревом," >&2
    echo "       и «ноль находок» здесь означало бы «ноль прочитанного»." >&2
    exit 2
fi

if [[ "$unpinned" -gt 0 ]]; then
    printf '%s\n' "${findings[@]}" >&2
    echo "" >&2
    echo "ОТКАЗ: шаг обязан подключаться по содержимому (40 шестнадцатеричных)." >&2
    echo "       Резолв тега: gh api repos/<owner>/<repo>/git/ref/tags/<tag>" >&2
    echo "       Версию оставляй комментарием рядом — её читает человек." >&2
    echo "       ОБЕ ПОЛОВИНЫ ДВИГАЕШЬ ТЫ: автообновление зависимостей снято" >&2
    echo "       2026-08-27, и ни хеш, ни комментарий больше не поправит никто." >&2
    echo "       Разойдутся — комментарий начнёт врать о том, что исполняется," >&2
    echo "       и врать молча: подпись читают, содержимое не проверяют." >&2
    exit 1
fi

echo "ok — каждый шаг подключён по содержимому"
